class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10
    ESCAPE_START = '&'
    NUMERIC_START = '#'
    HEX_PREFIX_LOWER = 'x'
    HEX_PREFIX_UPPER = 'X'
    SEMICOLON = ';'

    def __init__(self):
        pass

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                if self._process_numeric_entity(string, pos, out):
                    out, pos = out[1:], pos[0]
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string, pos):
        return (string[pos] == self.ESCAPE_START and 
                pos + 1 < len(string) and 
                string[pos + 1] == self.NUMERIC_START)

    def _process_numeric_entity(self, string, pos, out):
        length = len(string)
        start = pos + 2
        is_hex = False

        if start < length:
            first_char = string[start]
            if first_char in (self.HEX_PREFIX_LOWER, self.HEX_PREFIX_UPPER):
                start += 1
                is_hex = True

        if start == length:
            return None

        end = self._find_entity_end(string, start)

        if self._is_valid_entity_termination(string, end):
            entity_value = self._parse_entity_value(string, start, end, is_hex)
            if entity_value is not None:
                out.append(entity_value)
                return (chr(entity_value), end + 1)

        return None

    def _find_entity_end(self, string, start):
        end = start
        length = len(string)
        while end < length and self.is_hex_char(string[end]):
            end += 1
        return end

    def _is_valid_entity_termination(self, string, end):
        return end < len(string) and string[end] == self.SEMICOLON

    def _parse_entity_value(self, string, start, end, is_hex):
        base = self.HEX_BASE if is_hex else self.DECIMAL_BASE
        try:
            return int(string[start:end], base)
        except Exception:
            return None

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')
